scwin.___fireOver = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.checkVal = function() {
    return typeof grid2_tooltip == "undefined";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '분류1'항목에 마우스를 over한다.
    //1. After running the sample, mouse over 'Classification 1' item.
    WebSquare.wUnit.addCommand("set", "scwin.___fireOver('grid2_column5')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. '분류1'항목에 tooltip이 정상적으로 보여지지 않는다. (이전에는 tooltip이 보여지는 결함이 있었고 UI도 비정상적으로 길게 보여짐) 
    //1. Tooltip is not displayed normally in 'Category 1' item. (Previously there was a flaw showing the tooltip and the UI was looking abnormally long)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
